namespace ghidra.trace.model.target.info;








using ghidra.trace.model.target;
using ghidra.trace.model.target;
using ghidra.trace.model.target.iface;
using ghidra.trace.model.target.info.TraceObjectInterfaceFactory;
using ghidra.trace.model.target.schema;
using ghidra.util;
using ghidra.util.classfinder;

public class TraceObjectInterfaceUtils
{

	private static class Private {
		private Map<Class<object>, Constructor<object>> mapByClass = null;
		private Map<string, Constructor<object>> mapByName = null;

		public Private() {
			ClassSearcher.addChangeListener(this.classesChanged);
		}

		private void classesChanged(ChangeEvent evt) {
			mapByClass = null;
		}

		private void checkRefresh() {
			if (mapByClass == null) {
				List<TraceObjectInterfaceFactory> instances =
					ClassSearcher.getInstances(typeof(TraceObjectInterfaceFactory));
				if (instances.isEmpty()) {
					Msg.warn(this, "ClassSearcher not active, yet. " +
						"Falling back to built-in TraceObjectInterfaces.");
					instances = List.of(new BuiltinTraceObjectInterfaceFactory());
				}
				mapByClass = instances
						.stream()
						.flatMap(f => f.getInterfaceConstructors().stream())
						.collect(Collectors.toUnmodifiableMap(
							Constructor.iface,
							Function.identity()));
				mapByName = mapByClass.values()
						.stream()
						.collect(Collectors.toUnmodifiableMap(
							c => getSchemaName(c.iface()),
							Function.identity()));
			}
		}

		private Map<Class<object>, Constructor<object>> getMapByClass() {
			checkRefresh();
			return mapByClass;
		}

		private Map<string, Constructor<object>> getMapByName() {
			checkRefresh();
			return mapByName;
		}
	}

	private static readonly Private PRIVATE = new Private();

	public static Map<Class<object>, Constructor<object>> getAllConstructors() {
		return PRIVATE.getMapByClass();
	}

	public static Stream<Constructor<object>> streamConstructors(TraceObjectSchema schema) {
		return schema.getInterfaces().stream().map(PRIVATE.getMapByClass().get);
	}

	public static bool isTraceObject(Class<object> cls) {
		return cls == typeof(TraceObject) || typeof(TraceObjectInterface).isAssignableFrom(cls);
	}

	public static Map<string, Constructor<object>> getConstructorsByName() {
		return PRIVATE.getMapByName();
	}

	public static TraceObjectInfo requireAnnotation(Class<TraceObjectInterface> traceIf) {
		TraceObjectInfo annot = traceIf.getAnnotation(typeof(TraceObjectInfo));
		if (annot == null) {
			throw new IllegalArgumentException(
				traceIf + " is missing @" + typeof(TraceObjectInfo) + " annotation");
		}
		return annot;
	}

	public static string getSchemaName(Class<TraceObjectInterface> traceIf) {
		return requireAnnotation(traceIf).schemaName();
	}

	public static string getShortName(Class<TraceObjectInterface> traceIf) {
		return requireAnnotation(traceIf).shortName();
	}

	public static Collection<string> getFixedKeys(
			Class<TraceObjectInterface> traceIf) {
		return List.of(requireAnnotation(traceIf).fixedKeys());
	}

	public static T getValue<T>(TraceObject @object, long snap, string key, Class<T> cls, T def) {
		TraceObjectValue value = @object.getValue(snap, key);
		if (value == null) {
			return def;
		}
		return cls.cast(value.getValue());
	}
}
